def fake_volatility(prices):
    # A simple stand-in for calculate_stock_volatility.
    # Returns standard deviation as volatility for testing.
    if not prices or len(prices)<2:
        return 0.0
    mean = sum(prices) / len(prices)
    variance = sum((p - mean) ** 2 for p in prices) / (len(prices)-1)
    return variance ** 0.5

