def portfolio_risk_assessment(portfolio: dict) -> float:
    '''
    Takes a dict where keys are stock names and values have 'prices' list and 'allocation' float.
    For each stock, call calculate_stock_volatility(prices), multiply by allocation,
    sum all weighted volatilities. Returns: float representing total portfolio risk as weighted sum.
    '''

    # Chain-of-Thought:
    # 1. Initialize total_risk to 0.
    # 2. For each stock in the portfolio:
    #    a. Get prices (list) and allocation (float) for the stock.
    #    b. Call calculate_stock_volatility(prices) to get the stock's volatility.
    #    c. Multiply volatility by allocation for weighted volatility.
    #    d. Add weighted volatility to total_risk.
    # 3. Return total_risk.

    total_risk = 0.0

    for stock, info in portfolio.items():
        prices = info.get('prices', [])
        allocation = info.get('allocation', 0.0)
        stock_volatility = calculate_stock_volatility(prices)
        weighted_volatility = stock_volatility * allocation
        total_risk += weighted_volatility

    return total_risk


# Assuming definition: 
# portfolio_risk_assessment(portfolio_dict: dict) -> float
# Each stock dict: {'prices': [float], 'allocation': float}
# And helper: calculate_stock_volatility(prices: List[float]) -> float

# Sample mock for calculate_stock_volatility for standalone testing.
def calculate_stock_volatility(prices):
    # Simplified: standard deviation of returns
    if len(prices) < 2:
        return 0.0
    returns = [(prices[i+1] - prices[i]) / prices[i] for i in range(len(prices)-1)]
    mean = sum(returns) / len(returns)
    variance = sum((r - mean)**2 for r in returns) / len(returns)
    return variance**0.5

# Example test function stub for illustration
def portfolio_risk_assessment(portfolio):
    total_risk = 0.0
    for stock, info in portfolio.items():
        vol = calculate_stock_volatility(info['prices'])
        total_risk += vol * info['allocation']
    return total_risk

