def parse_sensor_reading(reading_str):
    '''
    Create a function called parse_sensor_reading that takes a string like 'T:25.5|H:60|TS:1234567890'. 
    Split by '|' to get parts. For each part, split by ':' to get key and value. 
    Return dict with 'temperature', 'humidity', 'timestamp' keys. 
    If a value cannot be converted to float/int, set to None. 
    Handle T as float, H as float, TS as int.
    '''
    # Step 1: Make an empty dictionary to hold the results
    result = {'temperature': None, 'humidity': None, 'timestamp': None}
    # Step 2: Split the string by '|'
    parts = reading_str.split('|')
    # Step 3: For each part, split by ':'
    for part in parts:
        if ':' not in part:
            continue  # skip malformed parts
        key, value = part.split(':', 1)
        key = key.strip()
        value = value.strip()
        if key == 'T':
            try:
                result['temperature'] = float(value)
            except ValueError:
                result['temperature'] = None
        elif key == 'H':
            try:
                result['humidity'] = float(value)
            except ValueError:
                result['humidity'] = None
        elif key == 'TS':
            try:
                result['timestamp'] = int(value)
            except ValueError:
                result['timestamp'] = None
    return result

# Example usage:
# print(parse_sensor_reading('T:25.5|H:60|TS:1234567890'))
# Output: {'temperature': 25.5, 'humidity': 60.0, 'timestamp': 1234567890}

